using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// "Ink &amp; Candy" map art, generated by code (16 px cells, 1 px ink outline, 3-step cel shading with the light
/// from the top-left, shadows shifted toward teal/magenta instead of just darker).
///  - ground tiles: quiet interiors (low contrast), so objects read as individual things
///  - standalone deposits: every tree / rock is its own outlined sprite (never a carpet)
///  - outline tiles for terrain boundaries (data-driven: edge bits + inner-corner dots, one set per terrain pair)
/// To restyle the whole map change the palette below and run BuildSim/Setup/1 Generate Art Assets again.
/// </summary>
public static class MapArt
{
    // ------------------------------------------------------------------ palette
    public static readonly Color32 Ink = new Color32(36, 34, 52, 255);          // outline colour (dark violet "black")
    private static readonly Color32 BorderInk = new Color32(22, 62, 50, 255);
    private static readonly Color32 DirtInk = new Color32(104, 56, 44, 255);
    private static readonly Color32 WaterRim = new Color32(190, 248, 255, 170);

    private struct Ramp { public Color32 shadow, baseC, light; public Ramp(Color32 s, Color32 b, Color32 l) { shadow = s; baseC = b; light = l; } }

    private static readonly Ramp GrassLight = new Ramp(new Color32(86, 196, 92, 255), new Color32(136, 230, 80, 255), new Color32(184, 248, 116, 255));
    private static readonly Ramp GrassMid = new Ramp(new Color32(70, 182, 92, 255), new Color32(114, 216, 66, 255), new Color32(164, 240, 100, 255));
    private static readonly Ramp GrassDark = new Ramp(new Color32(56, 160, 90, 255), new Color32(94, 196, 62, 255), new Color32(140, 226, 90, 255));
    private static readonly Ramp DirtRamp = new Ramp(new Color32(190, 112, 86, 255), new Color32(228, 164, 96, 255), new Color32(248, 204, 138, 255));
    private static readonly Ramp WaterRamp = new Ramp(new Color32(28, 150, 216, 255), new Color32(46, 198, 238, 255), new Color32(160, 242, 252, 255));
    private static readonly Ramp BushRamp = new Ramp(new Color32(28, 116, 104, 255), new Color32(52, 168, 112, 255), new Color32(120, 218, 138, 255));

    private static readonly Ramp[] TreeRamps =
    {
        new Ramp(new Color32(34, 148, 96, 255),  new Color32(86, 210, 72, 255),   new Color32(170, 242, 98, 255)),   // green
        new Ramp(new Color32(24, 118, 124, 255), new Color32(48, 196, 150, 255),  new Color32(144, 242, 192, 255)),  // teal
        new Ramp(new Color32(66, 150, 44, 255),  new Color32(152, 216, 52, 255),  new Color32(224, 248, 112, 255)),  // lime
        new Ramp(new Color32(186, 56, 78, 255),  new Color32(252, 150, 52, 255),  new Color32(255, 218, 104, 255)),  // autumn
    };

    private static readonly Ramp[] RockRamps =
    {
        new Ramp(new Color32(90, 84, 146, 255),  new Color32(160, 154, 206, 255), new Color32(228, 224, 252, 255)),  // lavender stone
        new Ramp(new Color32(90, 84, 146, 255),  new Color32(160, 154, 206, 255), new Color32(228, 224, 252, 255)),
        new Ramp(new Color32(128, 70, 92, 255),  new Color32(204, 136, 118, 255), new Color32(252, 204, 176, 255)),  // rust
        new Ramp(new Color32(90, 84, 146, 255),  new Color32(160, 154, 206, 255), new Color32(228, 224, 252, 255)),  // with a gem
    };

    // ------------------------------------------------------------------ entry
    /// <summary>Writes every map tile (ground, deposits, bushes, outlines) through ArtGenerator.WriteTile.</summary>
    public static void WriteGround(List<string> tiles)
    {
        for (int i = 0; i < 3; i++) ArtGenerator.WriteTile("Grass_Light_" + i, Grass(i, GrassLight), tiles);
        for (int i = 0; i < 4; i++) ArtGenerator.WriteTile("Grass_Mid_" + i, Grass(10 + i, GrassMid), tiles);
        for (int i = 0; i < 3; i++) ArtGenerator.WriteTile("Grass_Dark_" + i, Grass(20 + i, GrassDark), tiles);
        for (int i = 0; i < 5; i++) ArtGenerator.WriteTile("Grass_Decor_" + i, GrassDecor(30 + i, i), tiles);
        for (int i = 0; i < 3; i++) ArtGenerator.WriteTile("Dirt_" + i, Dirt(40 + i), tiles);
        for (int i = 0; i < 2; i++) ArtGenerator.WriteTile("Water_" + i, Water(50 + i), tiles);
        for (int i = 0; i < 3; i++) ArtGenerator.WriteTile("Bush_" + i, Bush(60 + i), tiles);

        // standalone deposits: trees are 16x20 (they overhang the cell above by 4 px; pivot at the trunk base)
        for (int i = 0; i < 4; i++) ArtGenerator.WriteTile("Tree_" + i, Tree(i), tiles, new Vector2(0.5f, 8f / 20f));
        for (int i = 0; i < 4; i++) ArtGenerator.WriteTile("Rock_" + i, Rock(i), tiles);

        // outline tiles: one set per terrain pair
        foreach (var set in new[] { "Coast", "Border", "Dirt" })
            for (int e = 0; e < 16; e++)
                for (int c = 0; c < 16; c++)
                    if (ValidEdge(e, c)) ArtGenerator.WriteTile("Edge_" + set + "_" + e + "_" + c, EdgeTile(set, e, c), tiles);
    }

    /// <summary>Pearl crates, 32x32 (2x2 cells): crate_closed_N / crate_open_N for the three looks.</summary>
    public static void WriteCrates()
    {
        for (int v = 0; v < 3; v++)
        {
            ArtGenerator.WriteSprite("crate_closed_" + v, CrateTex(v, false), 16);
            ArtGenerator.WriteSprite("crate_open_" + v, CrateTex(v, true), 16);
        }
    }

    private static Texture2D CrateTex(int v, bool open)
    {
        var p = new Px(32, 32);
        Color32 wood = v == 0 ? new Color32(214, 140, 84, 255) : (v == 1 ? new Color32(150, 128, 214, 255) : new Color32(250, 196, 70, 255));
        Color32 woodDark = v == 0 ? new Color32(160, 82, 78, 255) : (v == 1 ? new Color32(90, 74, 156, 255) : new Color32(214, 120, 52, 255));
        Color32 woodLight = v == 0 ? new Color32(246, 186, 120, 255) : (v == 1 ? new Color32(196, 180, 250, 255) : new Color32(255, 236, 150, 255));
        Color32 band = v == 0 ? new Color32(120, 62, 70, 255) : (v == 1 ? new Color32(70, 214, 224, 255) : new Color32(255, 250, 220, 255));
        Color32 gold = new Color32(255, 214, 80, 255), goldDark = new Color32(220, 140, 40, 255);
        Color32 shadow = new Color32(Ink.r, Ink.g, Ink.b, 70);

        // body
        p.Rect(4, 5, 24, 14, wood);
        p.Rect(24, 5, 4, 14, woodDark);                       // shaded right side
        p.Rect(4, 5, 24, 1, woodDark);                        // bottom edge
        for (int x = 10; x < 24; x += 6) p.Rect(x, 6, 1, 12, Mix(wood, woodDark, 0.6f));   // plank seams
        p.Rect(4, 17, 24, 2, woodLight);                      // light along the top of the body
        p.Rect(7, 5, 3, 14, band); p.Rect(22, 5, 3, 14, band);    // bands
        p.Rect(7, 5, 1, 14, Mix(band, Color.white, 0.35f));

        if (!open)
        {
            // lid (domed)
            p.Rect(3, 19, 26, 6, wood);
            p.Rect(4, 25, 24, 1, wood);
            p.Rect(3, 19, 1, 1, new Color32(0, 0, 0, 0)); p.Rect(28, 19, 1, 1, new Color32(0, 0, 0, 0));
            p.Rect(26, 19, 3, 6, woodDark);
            p.Rect(4, 24, 22, 2, woodLight);
            p.Rect(7, 19, 3, 7, band); p.Rect(22, 19, 3, 7, band);
            p.Rect(7, 19, 1, 7, Mix(band, Color.white, 0.35f));
            // lock plate
            p.Rect(14, 15, 4, 6, gold); p.Rect(17, 15, 1, 6, goldDark); p.Rect(14, 20, 4, 1, new Color32(255, 246, 170, 255));
            p.Set(15, 17, Ink); p.Set(15, 16, Ink);
        }
        else
        {
            // open: lid tipped back behind the box, pearls glowing inside
            p.Rect(4, 22, 24, 6, woodDark);
            p.Rect(4, 27, 24, 1, wood);
            p.Rect(7, 22, 3, 6, Mix(band, woodDark, 0.4f)); p.Rect(22, 22, 3, 6, Mix(band, woodDark, 0.4f));
            p.Rect(5, 19, 22, 3, new Color32(56, 36, 84, 255));                // dark inside
            p.Rect(4, 19, 24, 1, woodLight);
            Color32 pearl = new Color32(252, 246, 255, 255), pearlPink = new Color32(255, 196, 232, 255), pearlBlue = new Color32(176, 230, 255, 255);
            p.Disc(10.5f, 20.4f, 2.4f, pearlPink); p.Disc(16f, 21.4f, 2.8f, pearl); p.Disc(21.5f, 20.4f, 2.4f, pearlBlue);
            p.Set(15, 22, Color.white); p.Set(9, 21, Color.white); p.Set(20, 21, Color.white);
            // broken lock lying in front
            p.Rect(14, 6, 4, 3, gold); p.Rect(14, 6, 4, 1, goldDark);
        }

        p.Outline(Ink);
        p.Ellipse(16, 3.2f, 13f, 2.2f, shadow, true);
        return p.ToTex();
    }

    /// <summary>Build menu layer icons (28x28): materials, food, water, power.</summary>
    public static void WriteCategoryIcons()
    {
        ArtGenerator.WriteSprite("cat_materials", CatMaterials(), 16);
        ArtGenerator.WriteSprite("cat_food", CatFood(), 16);
        ArtGenerator.WriteSprite("cat_water", CatWater(), 16);
        ArtGenerator.WriteSprite("cat_power", CatPower(), 16);
    }

    // ---- shared helpers for the category icons: one light source (top-left), same shading depth on every icon
    private static bool[] MaskOf(Px p)
    {
        var m = new bool[p.w * p.h];
        for (int i = 0; i < m.Length; i++) m[i] = p.a[i].a > 200;
        return m;
    }

    private static bool M(bool[] m, int w, int h, int x, int y) { return x >= 0 && y >= 0 && x < w && y < h && m[y * w + x]; }

    /// <summary>Highlight (1 px) on the top-left rim, shadow (2 px) on the bottom-right rim, both hugging the shape.</summary>
    private static void Shade(Px p, bool[] mask, Color32 shadow, Color32 light)
    {
        for (int y = 0; y < p.h; y++) for (int x = 0; x < p.w; x++)
        {
            if (!M(mask, p.w, p.h, x, y)) continue;
            if (!M(mask, p.w, p.h, x + 2, y - 2) || !M(mask, p.w, p.h, x + 1, y - 1)) p.Set(x, y, shadow);
            else if (!M(mask, p.w, p.h, x - 1, y + 1) || !M(mask, p.w, p.h, x, y + 1) && !M(mask, p.w, p.h, x - 1, y)) p.Set(x, y, light);
        }
    }

    /// <summary>Removes pixels that stick out as single dots (fewer than 2 solid 4-neighbours).</summary>
    private static void Trim(Px p)
    {
        for (int pass = 0; pass < 2; pass++)
        {
            var m = MaskOf(p);
            for (int y = 0; y < p.h; y++) for (int x = 0; x < p.w; x++)
            {
                if (!m[y * p.w + x]) continue;
                int n = (M(m, p.w, p.h, x + 1, y) ? 1 : 0) + (M(m, p.w, p.h, x - 1, y) ? 1 : 0) + (M(m, p.w, p.h, x, y + 1) ? 1 : 0) + (M(m, p.w, p.h, x, y - 1) ? 1 : 0);
                if (n < 2) p.Set(x, y, new Color32(0, 0, 0, 0));
            }
        }
    }

    private static Texture2D CatMaterials()
    {
        // three equal true circles (12 px), bottom two first, top log on top with its own ink ring: a clean stack
        var p = new Px(28, 28);
        Color32 bark = new Color32(200, 120, 80, 255), barkDark = new Color32(140, 74, 74, 255), barkLight = new Color32(236, 170, 120, 255);
        Color32 face = new Color32(250, 206, 140, 255), core = new Color32(214, 140, 92, 255);
        int[][] logs = { new[] { 8, 7 }, new[] { 20, 7 }, new[] { 14, 18 } };
        foreach (var l in logs)
        {
            p.Disc(l[0], l[1], 6.9f, Ink);                       // own outline, drawn before the next log overlaps it
            var one = new Px(28, 28);
            one.Disc(l[0], l[1], 5.9f, bark);
            var mask = MaskOf(one);
            Shade(one, mask, barkDark, barkLight);
            for (int i = 0; i < one.a.Length; i++) if (one.a[i].a > 0) p.a[i] = one.a[i];
            p.Disc(l[0], l[1], 3.9f, face);                      // end face
            p.Disc(l[0], l[1], 1.5f, core);                      // heart
        }
        p.Outline(Ink);
        return p.ToTex();
    }

    private static Texture2D CatFood()
    {
        // slim, tapered fish: pointed snout, forked tail, swept-back dorsal fin, eye, light belly
        var p = new Px(28, 28);
        Color32 body = new Color32(60, 190, 240, 255), bodyDark = new Color32(28, 130, 210, 255), bodyLight = new Color32(190, 244, 255, 255), belly = new Color32(160, 232, 252, 255);
        Color32 fin = new Color32(255, 160, 70, 255), finDark = new Color32(220, 100, 50, 255), finLight = new Color32(255, 214, 140, 255);

        var fins = new Px(28, 28);
        fins.Poly(new[] { new Vector2(19.5f, 14.5f), new Vector2(26.5f, 22f), new Vector2(24.5f, 14f), new Vector2(26.5f, 6f), new Vector2(19.5f, 13f) }, fin);   // forked tail
        fins.Poly(new[] { new Vector2(8.5f, 17.5f), new Vector2(10.5f, 24f), new Vector2(20f, 21f), new Vector2(15f, 16.5f) }, fin);                              // dorsal fin, swept back
        Shade(fins, MaskOf(fins), finDark, finLight);

        var bodyPx = new Px(28, 28);
        bodyPx.Poly(new[] { new Vector2(1f, 13.5f), new Vector2(5f, 17.5f), new Vector2(10f, 19f), new Vector2(15f, 18f), new Vector2(21f, 14.5f), new Vector2(21f, 13.2f), new Vector2(15f, 9.5f), new Vector2(10f, 8.5f), new Vector2(5f, 9.8f) }, body);
        Shade(bodyPx, MaskOf(bodyPx), bodyDark, bodyLight);
        for (int y = 10; y <= 12; y++) for (int x = 5; x <= 16; x++)
        {
            var c = bodyPx.a[y * 28 + x];
            if (c.r == body.r && c.g == body.g && c.b == body.b) bodyPx.Set(x, y, belly);                       // belly stripe
        }

        for (int i = 0; i < p.a.Length; i++) { if (fins.a[i].a > 0) p.a[i] = fins.a[i]; if (bodyPx.a[i].a > 0) p.a[i] = bodyPx.a[i]; }
        p.Rect(4, 14, 2, 2, Color.white); p.Set(4, 14, Ink);                                                      // eye
        Trim(p);
        p.Outline(Ink);
        return p.ToTex();
    }

    private static Texture2D CatWater()
    {
        // a real drop: symmetric round bulb, tip with slightly concave sides
        var p = new Px(28, 28);
        Color32 w = new Color32(60, 190, 240, 255), wd = new Color32(28, 130, 210, 255), wl = new Color32(190, 244, 255, 255);
        const float cx = 14f, cy = 9.5f, r = 8f;
        for (int y = 0; y < 28; y++) for (int x = 0; x < 28; x++)
        {
            float dx = x + 0.5f - cx, dy = y + 0.5f - cy;
            bool inBulb = dx * dx + dy * dy <= r * r;
            bool inTip = false;
            if (y + 0.5f > cy + 4f && y + 0.5f <= 26.5f)
            {
                float t = (y + 0.5f - (cy + 4f)) / (26.5f - (cy + 4f));            // 0 at the bulb, 1 at the tip
                float half = 6.9f * Mathf.Pow(1f - t, 1.7f);                          // concave sides
                inTip = Mathf.Abs(dx) <= half;
            }
            if (inBulb || inTip) p.Set(x, y, w);
        }
        var mask = MaskOf(p);
        Shade(p, mask, wd, wl);
        p.Rect(9, 9, 2, 4, wl);                                                       // glint
        Trim(p);
        p.Outline(Ink);
        return p.ToTex();
    }

    private static Texture2D CatPower()
    {
        // bolt with constant edge slopes (1:2, 1:1, 1:3) and a bold, closed point
        var p = new Px(28, 28);
        Color32 y1 = new Color32(255, 226, 70, 255), y2 = new Color32(255, 160, 40, 255), y3 = new Color32(255, 248, 170, 255);
        p.Poly(new[] { new Vector2(13, 27), new Vector2(22, 27), new Vector2(16, 15), new Vector2(23, 15), new Vector2(9, 1), new Vector2(13, 13), new Vector2(6, 13) }, y1);
        var mask = MaskOf(p);
        Shade(p, mask, y2, y3);
        Trim(p);
        p.Outline(Ink);
        return p.ToTex();
    }

    /// <summary>Fisher hut (40x32) and the fish icon (12x12).</summary>
    public static void WriteFisher()
    {
        ArtGenerator.WriteSprite("hut_fisher", HutTex(), 16);
        ArtGenerator.WriteSprite("icon_fish", FishIcon(), 16);
    }

    private static Texture2D HutTex()
    {
        var p = new Px(40, 32);
        Color32 wood = new Color32(214, 150, 96, 255), woodDark = new Color32(160, 92, 84, 255), woodLight = new Color32(246, 196, 132, 255);
        Color32 roof = new Color32(46, 190, 214, 255), roofDark = new Color32(30, 122, 178, 255), roofLight = new Color32(150, 240, 246, 255);
        // walls
        p.Rect(6, 3, 28, 13, wood);
        p.Rect(28, 3, 6, 13, woodDark);
        for (int x = 11; x < 28; x += 5) p.Rect(x, 4, 1, 11, Mix(wood, woodDark, 0.55f));
        p.Rect(6, 14, 28, 2, woodLight);
        // door
        p.Rect(16, 3, 7, 10, new Color32(70, 44, 80, 255));
        p.Rect(16, 12, 7, 1, new Color32(110, 70, 110, 255));
        p.Set(21, 7, new Color32(255, 214, 80, 255));
        // roof (triangle with eaves)
        p.Poly(new[] { new Vector2(2, 15), new Vector2(20, 31), new Vector2(38, 15) }, roof);
        for (int y = 15; y < 32; y++) for (int x = 0; x < 40; x++)
        {
            if (!p.Solid(x, y)) continue;
            var c = p.a[y * 40 + x];
            if (!(c.r == roof.r && c.g == roof.g && c.b == roof.b)) continue;
            if (x > 20 + (31 - y) * 0.0f + 1) p.Set(x, y, roofDark);                  // right half in shade
            else if (x + y < 38) p.Set(x, y, roofLight);                              // left edge catches the light
            if ((y % 4) == 0 && x > 6 && x < 34) p.Set(x, y, Mix(p.a[y * 40 + x], roofDark, 0.5f));   // shingle rows
        }
        // fish sign + buoy
        p.Ellipse(28f, 9.5f, 3.2f, 2.0f, new Color32(255, 150, 60, 255));
        p.Poly(new[] { new Vector2(30.5f, 9.5f), new Vector2(33.5f, 12), new Vector2(33.5f, 7) }, new Color32(255, 150, 60, 255));
        p.Set(26, 10, Ink);
        p.Disc(10.5f, 7f, 2.4f, new Color32(255, 96, 110, 255));
        p.Rect(9, 7, 3, 1, new Color32(255, 250, 240, 255));
        p.Outline(Ink);
        p.Ellipse(20, 2f, 17f, 1.8f, new Color32(Ink.r, Ink.g, Ink.b, 70), true);
        return p.ToTex();
    }

    /// <summary>Worker face icon (8x7): the head cut out of the miner's first frame (columns 12-19, rows 18-24 from the top).</summary>
    public static void WriteWorkerIcon()
    {
        const int x0 = 12, top = 18, w = 8, h = 7;
        var src = new Texture2D(2, 2);
        src.LoadImage(System.IO.File.ReadAllBytes("Assets/Textures/Original/Outline/MiniMiner.png"));
        var all = src.GetPixels32();
        int y0 = src.height - top - h, sw = src.width;
        var px = new Color32[w * h];                                // bottom row first
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) px[y * w + x] = all[(y0 + y) * sw + x0 + x];
        Object.DestroyImmediate(src);
        Color32 ink = px[(h - 1 - 3) * w];                          // outline colour: left edge, 4th row from the top
        for (int y = 0; y < h; y++) if (px[y * w + w - 1].a > 0) px[y * w + w - 1] = ink;   // the pickaxe pokes into the right edge
        var t = ArtGenerator.NewTex(w, h);
        t.SetPixels32(px);
        ArtGenerator.WriteSprite("icon_worker", t, 16);
    }

    /// <summary>House (18x17): one tile, wooden walls, red roof, chimney.</summary>
    public static void WriteHouse()
    {
        var p = new Px(18, 17);
        Color32 wall = new Color32(214, 150, 96, 255), wallDark = new Color32(160, 92, 84, 255);
        Color32 roof = new Color32(214, 84, 72, 255), roofDark = new Color32(160, 56, 70, 255), roofLight = new Color32(250, 138, 110, 255);
        p.Rect(3, 1, 12, 7, wall);
        p.Rect(11, 1, 4, 7, wallDark);
        p.Rect(7, 1, 3, 5, new Color32(70, 44, 80, 255));
        p.Rect(4, 4, 2, 2, new Color32(255, 214, 80, 255));
        p.Rect(12, 9, 2, 6, new Color32(150, 150, 176, 255));      // chimney (the roof covers its lower part)
        p.Poly(new[] { new Vector2(1, 7), new Vector2(9, 15), new Vector2(17, 7) }, roof);
        for (int y = 7; y < 16; y++) for (int x = 0; x < 18; x++)
        {
            var c = p.a[y * 18 + x];
            if (!(c.r == roof.r && c.g == roof.g && c.b == roof.b)) continue;
            p.Set(x, y, x > 9 ? roofDark : (x + y < 17 ? roofLight : roof));
        }
        p.Outline(Ink);
        ArtGenerator.WriteSprite("house", p.ToTex(), 16);
    }

    /// <summary>Stone icon (12x11, faceted boulder) and wood icon (14x13, pile of three log ends).</summary>
    public static void WriteResourceIcons()
    {
        ArtGenerator.WriteSprite("icon_stone", StoneIcon(), 16);
        ArtGenerator.WriteSprite("icon_wood", WoodIcon(), 16);
    }

    private static Texture2D StoneIcon()
    {
        var p = new Px(12, 11);
        Color32 baseC = new Color32(142, 142, 172, 255), dark = new Color32(96, 94, 130, 255), light = new Color32(206, 206, 230, 255);
        p.Poly(new[] { new Vector2(2, 1), new Vector2(1, 4), new Vector2(2, 8), new Vector2(5, 10), new Vector2(8, 9), new Vector2(10, 6), new Vector2(10, 2), new Vector2(8, 1) }, baseC);
        for (int y = 0; y < p.h; y++) for (int x = 0; x < p.w; x++)
        {
            if (!p.Solid(x, y)) continue;
            if (x >= 7 || y <= 2) p.Set(x, y, dark);
            else if (x <= 4 && y >= 6) p.Set(x, y, light);
        }
        p.Set(5, 6, dark); p.Set(6, 5, dark); p.Set(6, 4, dark);
        p.Outline(Ink);
        return p.ToTex();
    }

    private static Texture2D WoodIcon()
    {
        var p = new Px(14, 13);
        Color32 bark = new Color32(122, 74, 42, 255), wood = new Color32(232, 176, 108, 255), ring = new Color32(186, 120, 68, 255);
        foreach (var c in new[] { new Vector2(4.5f, 3.5f), new Vector2(9.5f, 3.5f), new Vector2(7.5f, 8.5f) })
        {
            p.Disc(c.x, c.y, 3.0f, bark);
            p.Disc(c.x, c.y, 2.2f, wood);
            p.Disc(c.x, c.y, 1.4f, ring);
            p.Disc(c.x, c.y, 0.6f, wood);
        }
        p.Outline(Ink);
        return p.ToTex();
    }

    private static Texture2D FishIcon()
    {
        var p = new Px(12, 12);
        Color32 body = new Color32(60, 190, 240, 255), belly = new Color32(190, 244, 255, 255), fin = new Color32(255, 160, 70, 255);
        p.Ellipse(5.2f, 6f, 4.4f, 3f, body);
        p.Poly(new[] { new Vector2(8.5f, 6), new Vector2(11.5f, 9), new Vector2(11.5f, 3) }, fin);
        p.Rect(2, 4, 6, 1, belly);
        p.Set(3, 7, Ink);
        p.Outline(Ink);
        return p.ToTex();
    }

    /// <summary>Index into TerrainOutliner's tile arrays.</summary>
    public static int EdgeIndex(int edges, int corners) { return (edges << 4) | corners; }

    /// <summary>A corner dot is only drawn where neither neighbouring edge is drawn (and something must be drawn at all).</summary>
    public static bool ValidEdge(int e, int c)
    {
        if (e == 0 && c == 0) return false;
        for (int i = 0; i < 4; i++)
            if ((c & (1 << i)) != 0 && (e & ((1 << i) | (1 << ((i + 1) % 4)))) != 0) return false;
        return true;
    }

    // ------------------------------------------------------------------ pixel canvas
    private class Px
    {
        public readonly int w, h;
        public readonly Color32[] a;
        public Px(int w, int h) { this.w = w; this.h = h; a = new Color32[w * h]; }

        public bool In(int x, int y) { return x >= 0 && y >= 0 && x < w && y < h; }
        public void Set(int x, int y, Color32 c) { if (In(x, y)) a[y * w + x] = c; }
        public bool Solid(int x, int y) { return In(x, y) && a[y * w + x].a > 200; }
        public bool Empty(int x, int y) { return In(x, y) && a[y * w + x].a == 0; }

        public void Disc(float cx, float cy, float r, Color32 c)
        {
            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
                if ((x + 0.5f - cx) * (x + 0.5f - cx) + (y + 0.5f - cy) * (y + 0.5f - cy) <= r * r) a[y * w + x] = c;
        }

        public void Ellipse(float cx, float cy, float rx, float ry, Color32 c, bool onlyEmpty = false)
        {
            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
            {
                float dx = (x + 0.5f - cx) / rx, dy = (y + 0.5f - cy) / ry;
                if (dx * dx + dy * dy > 1f) continue;
                if (onlyEmpty && a[y * w + x].a != 0) continue;
                a[y * w + x] = c;
            }
        }

        public void Rect(int x, int y, int rw, int rh, Color32 c) { for (int j = 0; j < rh; j++) for (int i = 0; i < rw; i++) Set(x + i, y + j, c); }

        public void Poly(Vector2[] pts, Color32 c)
        {
            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
                if (Inside(pts, new Vector2(x + 0.5f, y + 0.5f))) a[y * w + x] = c;
        }

        /// <summary>1 px outline around everything opaque (4-neighbour dilation).</summary>
        public void Outline(Color32 ink)
        {
            var src = (Color32[])a.Clone();
            for (int y = 0; y < h; y++) for (int x = 0; x < w; x++)
            {
                if (src[y * w + x].a != 0) continue;
                if ((x > 0 && src[y * w + x - 1].a > 200) || (x < w - 1 && src[y * w + x + 1].a > 200) ||
                    (y > 0 && src[(y - 1) * w + x].a > 200) || (y < h - 1 && src[(y + 1) * w + x].a > 200))
                    a[y * w + x] = ink;
            }
        }

        public Texture2D ToTex()
        {
            var t = ArtGenerator.NewTex(w, h);
            t.SetPixels32(a);
            return t;
        }

        private static bool Inside(Vector2[] poly, Vector2 p)
        {
            bool inside = false;
            for (int i = 0, j = poly.Length - 1; i < poly.Length; j = i++)
                if ((poly[i].y > p.y) != (poly[j].y > p.y) && p.x < (poly[j].x - poly[i].x) * (p.y - poly[i].y) / (poly[j].y - poly[i].y) + poly[i].x) inside = !inside;
            return inside;
        }
    }

    private static float R(int x, int y, int seed)
    {
        unchecked
        {
            uint h = (uint)(x * 374761393 + y * 668265263 + seed * 144665);
            h = (h ^ (h >> 13)) * 1274126177u;
            h ^= h >> 16;
            return (h & 0xFFFF) / 65535f;
        }
    }

    private static Color32 Mix(Color32 a, Color32 b, float t) { return Color32.Lerp(a, b, t); }

    // ------------------------------------------------------------------ ground (quiet interiors)
    private static Texture2D Grass(int seed, Ramp r)
    {
        var p = new Px(16, 16);
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++)
        {
            float v = R(x, y, seed);
            Color32 c = r.baseC;
            if (v < 0.07f) c = Mix(r.baseC, r.light, 0.45f);
            else if (v < 0.13f) c = Mix(r.baseC, r.shadow, 0.35f);
            p.Set(x, y, c);
        }
        return p.ToTex();
    }

    private static Texture2D GrassDecor(int seed, int kind)
    {
        var p = new Px(16, 16);
        var r = GrassMid;
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++) p.Set(x, y, R(x, y, seed) < 0.06f ? Mix(r.baseC, r.light, 0.4f) : r.baseC);
        int cx = 4 + (int)(R(1, 1, seed) * 8), cy = 3 + (int)(R(2, 2, seed) * 8);
        if (kind <= 1)
        {
            // grass tuft: a little fan of blades
            p.Set(cx, cy, r.shadow); p.Set(cx, cy + 1, r.shadow); p.Set(cx - 1, cy + 2, r.shadow); p.Set(cx + 1, cy + 2, r.shadow);
            p.Set(cx, cy + 2, r.light);
            if (kind == 1) { p.Set(cx + 4, cy - 1, r.shadow); p.Set(cx + 4, cy, r.light); }
        }
        else
        {
            Color32 petal = kind == 2 ? new Color32(255, 252, 240, 255) : (kind == 3 ? new Color32(255, 214, 70, 255) : new Color32(255, 128, 176, 255));
            Color32 core = kind == 3 ? new Color32(255, 150, 40, 255) : new Color32(255, 214, 70, 255);
            p.Set(cx, cy, r.shadow);                                                     // stem
            p.Set(cx, cy + 2, core);
            p.Set(cx - 1, cy + 2, petal); p.Set(cx + 1, cy + 2, petal); p.Set(cx, cy + 1, petal); p.Set(cx, cy + 3, petal);
        }
        return p.ToTex();
    }

    private static Texture2D Dirt(int seed)
    {
        var p = new Px(16, 16);
        var r = DirtRamp;
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++)
        {
            float v = R(x, y, seed);
            Color32 c = r.baseC;
            if (v < 0.07f) c = Mix(r.baseC, r.light, 0.5f);
            else if (v < 0.14f) c = Mix(r.baseC, r.shadow, 0.5f);
            p.Set(x, y, c);
        }
        // two little pebbles (light top-left, shadow bottom-right)
        for (int i = 0; i < 2; i++)
        {
            int px = 2 + (int)(R(i, 5, seed) * 11), py = 2 + (int)(R(i, 6, seed) * 11);
            p.Set(px, py, new Color32(246, 232, 220, 255)); p.Set(px + 1, py, new Color32(214, 190, 190, 255));
            p.Set(px, py - 1, new Color32(190, 150, 150, 255)); p.Set(px + 1, py - 1, r.shadow);
        }
        return p.ToTex();
    }

    private static Texture2D Water(int seed)
    {
        var p = new Px(16, 16);
        var r = WaterRamp;
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++)
            p.Set(x, y, (y % 5 == 0 && R(x, y, seed) < 0.35f) ? Mix(r.baseC, r.shadow, 0.55f) : r.baseC);
        // short light wave strokes
        for (int i = 0; i < 3; i++)
        {
            int gx = 1 + (int)(R(i, 7, seed) * 10), gy = 2 + (int)(R(i, 8, seed) * 12);
            p.Set(gx, gy, r.light); p.Set(gx + 1, gy, r.light); p.Set(gx + 2, gy, Mix(r.light, r.baseC, 0.5f));
        }
        return p.ToTex();
    }

    private static Texture2D Bush(int seed)
    {
        var p = new Px(16, 16);
        var r = BushRamp;
        int ox = (int)(R(1, 2, seed) * 2) - 1;
        p.Disc(8 + ox, 8, 5.6f, r.baseC);
        p.Disc(5 + ox, 7, 3.8f, r.baseC);
        p.Disc(11 + ox, 7, 3.8f, r.baseC);
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++)
        {
            if (!p.Solid(x, y)) continue;
            float v = (x - 8) * 0.6f - (y - 8) * 0.8f;
            if (v > 3.4f) p.Set(x, y, r.shadow);
            else if (v < -4.4f) p.Set(x, y, r.light);
        }
        p.Outline(BorderInk);
        return p.ToTex();
    }

    // ------------------------------------------------------------------ standalone deposits
    private static Texture2D Tree(int variant)
    {
        var p = new Px(16, 20);
        var r = TreeRamps[variant];
        float jx = variant == 1 ? 0.6f : (variant == 3 ? -0.5f : 0f);

        // trunk (dark right side), partly hidden by the canopy
        Color32 bark = new Color32(150, 92, 62, 255), barkDark = new Color32(104, 58, 60, 255);
        p.Rect(7, 2, 2, 7, bark); p.Rect(8, 2, 1, 7, barkDark);
        p.Rect(6, 2, 4, 1, barkDark);                                                  // root flare

        // canopy: three overlapping discs
        p.Disc(8 + jx, 13.2f, 6.2f, r.baseC);
        p.Disc(4.6f + jx, 11.4f, 4.2f, r.baseC);
        p.Disc(11.4f + jx, 11.4f, 4.2f, r.baseC);
        for (int y = 7; y < 20; y++) for (int x = 0; x < 16; x++)
        {
            if (!p.Solid(x, y) || p.a[y * 16 + x].Equals(bark) || p.a[y * 16 + x].Equals(barkDark)) continue;
            if (!(p.a[y * 16 + x].r == r.baseC.r && p.a[y * 16 + x].g == r.baseC.g && p.a[y * 16 + x].b == r.baseC.b)) continue;
            float v = (x - 8) * 0.65f - (y - 12.5f) * 0.85f;                           // bottom-right = shadow
            if (v > 3.6f) p.Set(x, y, r.shadow);
            else if (v < -4.6f) p.Set(x, y, r.light);
        }
        p.Disc(6.2f + jx, 15.6f, 2.0f, r.light);                                       // sparkle blob
        for (int i = 0; i < 4; i++) p.Set(4 + (int)(R(i, 3, variant + 90) * 8), 9 + (int)(R(i, 4, variant + 90) * 6), Mix(r.baseC, r.light, 0.6f));

        p.Outline(Ink);
        p.Ellipse(8, 1.6f, 5.2f, 1.5f, new Color32(Ink.r, Ink.g, Ink.b, 70), true);   // soft ground shadow, outside the outline
        return p.ToTex();
    }

    private static Texture2D Rock(int variant)
    {
        var p = new Px(16, 16);
        var r = RockRamps[variant];
        // lumpy boulder: polygon around (8,7.5) with per-variant jitter, flat on the bottom
        var pts = new List<Vector2>();
        float rad = variant == 1 ? 4.6f : 5.8f;
        for (int i = 0; i < 9; i++)
        {
            float ang = Mathf.PI * 2f * i / 9f + variant * 0.4f;
            float rr = rad + (R(i, 11, variant + 7) - 0.5f) * 2.4f;
            float x = 8f + Mathf.Cos(ang) * rr, y = 7.5f + Mathf.Sin(ang) * rr * 0.86f;
            pts.Add(new Vector2(x, Mathf.Max(y, 3f)));
        }
        p.Poly(pts.ToArray(), r.baseC);
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++)
        {
            if (!p.Solid(x, y)) continue;
            float v = (x - 8) * 0.7f - (y - 7.5f) * 0.9f;
            if (v > 2.6f) p.Set(x, y, r.shadow);
            else if (v < -3.4f) p.Set(x, y, r.light);
        }
        p.Set(5, 10, r.light); p.Set(6, 10, r.light); p.Set(5, 9, r.light);            // glint
        p.Set(9, 7, r.shadow); p.Set(10, 6, r.shadow); p.Set(10, 5, r.shadow);         // crack
        if (variant == 1) { p.Disc(11.6f, 4.4f, 2.0f, r.baseC); p.Set(12, 4, r.shadow); }
        if (variant == 3)
        {
            Color32 gem = new Color32(46, 214, 240, 255), gemLight = new Color32(200, 252, 255, 255);
            p.Poly(new[] { new Vector2(6, 6), new Vector2(8, 10), new Vector2(10, 6) }, gem);
            p.Set(8, 9, gemLight); p.Set(7, 7, gemLight);
        }
        p.Outline(Ink);
        p.Ellipse(8, 2f, 5.4f, 1.4f, new Color32(Ink.r, Ink.g, Ink.b, 70), true);
        return p.ToTex();
    }

    // ------------------------------------------------------------------ outline tiles
    /// <summary>
    /// Edge bits: 1=N 2=E 4=S 8=W, corner bits: 1=NE 2=SE 4=SW 8=NW. The ink line sits on the inside border of the
    /// cell; coast tiles also get a light rim just inside it (the water "pops" at the shore).
    /// </summary>
    private static Texture2D EdgeTile(string set, int e, int c)
    {
        var p = new Px(16, 16);
        Color32 ink = set == "Coast" ? Ink : (set == "Border" ? BorderInk : DirtInk);
        bool rim = set == "Coast";
        // rim first (so the ink wins where they meet)
        if (rim)
        {
            if ((e & 1) != 0) for (int x = 1; x < 15; x++) p.Set(x, 14, WaterRim);
            if ((e & 2) != 0) for (int y = 1; y < 15; y++) p.Set(14, y, WaterRim);
            if ((e & 4) != 0) for (int x = 1; x < 15; x++) p.Set(x, 1, WaterRim);
            if ((e & 8) != 0) for (int y = 1; y < 15; y++) p.Set(1, y, WaterRim);
        }
        for (int i = 0; i < 16; i++)
        {
            if ((e & 1) != 0) p.Set(i, 15, ink);
            if ((e & 2) != 0) p.Set(15, i, ink);
            if ((e & 4) != 0) p.Set(i, 0, ink);
            if ((e & 8) != 0) p.Set(0, i, ink);
        }
        // inner-corner dots close the line around a concave corner
        if ((c & 1) != 0) p.Set(15, 15, ink);
        if ((c & 2) != 0) p.Set(15, 0, ink);
        if ((c & 4) != 0) p.Set(0, 0, ink);
        if ((c & 8) != 0) p.Set(0, 15, ink);
        return p.ToTex();
    }
}
